pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if let Some(payload) = bytes.strip_prefix("v:2;hello:") {
        return Ok(Msg::Hello(payload.into()));
    }
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    eprintln!("decode error: unknown message");
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!("v:2;hello:{value}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ping_encode_roundtrip() {
        assert!(matches!(decode(&encode(&Msg::Ping)), Ok(Msg::Ping)));
    }

    #[test]
    fn hello_encode_roundtrip() {
        let message = Msg::Hello("desktop:client".into());
        assert!(matches!(decode(&encode(&message)), Ok(Msg::Hello(value)) if value == "desktop:client"));
    }

    #[test]
    fn hello_uses_v2_envelope() {
        assert_eq!(encode(&Msg::Hello("client".into())), "v:2;hello:client");
    }
}
